"""Session token cache used by the gateway request handler."""

import time

_CACHE = {}
_TTL_SECONDS = 300


def get_session(session_id, loader):
    """Return the cached session for session_id, loading it on miss."""
    entry = _CACHE.get(session_id)
    now = time.time()
    if entry is not None and now - entry["at"] < _TTL_SECONDS:
        return entry["value"]

    value = loader(session_id)
    _CACHE[session_id] = {"value": value, "at": now}

    if len(_CACHE) > 5000:
        oldest = min(_CACHE, key=lambda k: _CACHE[k]["at"])
        del _CACHE[oldest]

    return value
